NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Amos'

CHAPTERS = {
    1: {
        1: 'Besede Amosa, ki je bil med čredniki iz Tekóe, ki jih je videl glede Izraela v dneh Uzíjaha, Judovega kralja in v dneh Jerobeáma, Jehoáševega sina, Izraelovega kralja, dve leti pred potresom.',
        2: 'Rekel je: » Gospod bo rjovel iz Siona in izustil svoj glas iz Jeruzalema in prebivališča pastirjev bodo žalovala in vrh Karmela se bo posušil.«',
        3: 'Tako govori Gospod: »Zaradi treh prestopkov Damaska in zaradi štirih ne bom odvrnil njegove kazni, ker so Gileád mlatili z mlatilnimi orodji iz železa.',
        4: 'Temveč bom poslal ogenj v Hazaélovo hišo, ki bo použil Ben Hadádove palače.',
        5: 'Zlomil bom tudi zapah Damaska in iztrebil prebivalca iz ravnine Aven in tistega, ki drži žezlo, iz edenske hiše in ljudstvo iz Sirije bo šlo v ujetništvo v Kir,« govori Gospod.',
        6: 'Tako govori Gospod: »Zaradi treh prestopkov Gaze in zaradi štirih ne bom odvrnil njene kazni, ker so odvedli proč ujete, celotno ujetništvo, da jih izročijo Edómu;',
        7: 'toda poslal bom ogenj na obzidje Gaze, ki bo pogoltnil njene palače',
        8: 'in iztrebil bom prebivalca iz Ašdóda in tistega, ki drži žezlo iz Aškelóna. Svojo roko bom obrnil zoper Ekrón in preostanek Filistejcev bo izginil,« govori Gospod Bog.',
        9: 'Tako govori Gospod: »Zaradi treh prestopkov Tira in zaradi štirih ne bom odvrnil njegove kazni, ker so celotno ujetništvo izročili Edómu in se niso spomnili bratske zaveze.',
        10: 'Toda jaz bom na obzidje Tira poslal ogenj, ki bo požrl njegove palače.«',
        11: 'Tako govori Gospod: »Zaradi treh prestopkov Edóma in zaradi štirih ne bom odvrnil njegove kazni, ker je svojega brata zasledoval z mečem in zavrgel vse usmiljenje in je njegova jeza neprestano trgala in je svoj bes ohranjal na veke;',
        12: 'toda poslal bom ogenj nad Temán, ki bo požrl palače v Bocri.«',
        13: 'Tako govori Gospod: »Zaradi treh prestopkov Amónovih otrok in zaradi štirih ne bom odvrnil njegove kazni, ker so razparali nosečnice iz Gileáda, da bi lahko razširili svojo mejo.',
        14: 'Toda jaz bom zanetil ogenj na obzidju Rabe in ta bo požrl njene palače z vpitjem na dan bitke, z viharjem na dan vrtinčastega vetra.',
        15: 'Njihov kralj bo šel v ujetništvo, on in njegovi princi skupaj,« govori Gospod.',
    },
    2: {
        1: 'Tako govori Gospod: »Zaradi treh prestopkov Moába in zaradi štirih ne bom odvrnil njegove kazni, ker je kosti edómskega kralja sežgal v žganem apnu.',
        2: 'Toda jaz bom poslal ogenj nad Moáb in ta bo požrl palače Kerijóta, in Moáb bo umrl s hrupom, z vpitjem in z zvokom šofarja.',
        3: 'Iztrebil bom sodnika iz njegove srede in z njim bom ubil vse njegove prince,« govori Gospod.',
        4: 'Tako govori Gospod: »Zaradi treh prestopkov Juda in zaradi štirih ne bom odvrnil njegove kazni; ker so prezirali Gospodovo postavo in se niso držali njegovih zapovedi in njihove laži so jim povzročile, da se motijo, za katerimi so hodili njihovi očetje.',
        5: 'Toda jaz bom poslal ogenj nad Juda in ta bo požrl jeruzalemske palače.«',
        6: 'Tako govori Gospod: »Zaradi treh prestopkov Izraela in zaradi štirih ne bom odvrnil njegove kazni, ker so pravičnega prodajali za srebro in revnega za par čevljev,',
        7: 'ki koprnijo po zemeljskem prahu na glavi revnega in zavijajo pot krotkega. Moški in njegov oče bosta šla noter k isti deklici, da oskrunita moje sveto ime.',
        8: 'Ob vsakem oltarju legajo na oblačila, položena za jamstvo in pijejo vino obsojenih v hiši svojega boga.',
        9: 'Čeprav sem pred njimi uničil Amoréjca, katerega višina je bila podobna višini ceder in je bil močan kakor hrasti, vendar sem uničil njegov sad od zgoraj in njegove korenine od spodaj.',
        10: 'Privedel sem vas tudi iz egiptovske dežele in vas štirideset let vodil skozi divjino, da vzamete v last deželo Amoréjca.',
        11: 'Izmed vaših sinov sem dvignil preroke in izmed vaših mladeničev nazirce. Mar ni to celo tako, oh vi Izraelovi otroci?« govori Gospod.',
        12: '»Toda nazircem ste dajali piti vino in prerokom zapovedovali, rekoč: ›Ne prerokujte.‹',
        13: 'Glejte, stlačen sem pod vami, kakor je stlačen voz, ki je poln snopov.',
        14: 'Zato bo pred naglim izginil umik in močni ne bo okrepil svoje moči niti mogočni sebe ne bo osvobodil',
        15: 'niti ne bo stal tisti, ki prijema lok in kdor je naglih stopal sebe ne bo osvobodil niti kdor jaha konja sebe ne bo osvobodil.',
        16: 'In kdor je pogumen med mogočnimi, bo na ta dan nag pobegnil proč,« govori Gospod.',
    },
    3: {
        1: 'Poslušajte to besedo, ki jo je Gospod govoril zoper vas, oh Izraelovi otroci, zoper celotno družino, ki sem jo privedel iz egiptovske dežele, rekoč:',
        2: '»Samo vas sem poznal izmed vseh zemeljskih družin, zato vas bom kaznoval zaradi vseh vaših krivičnosti.',
        3: 'Mar lahko dva hodita skupaj, razen če se strinjata?',
        4: 'Ali bo lev rjovel v gozdu, kadar nima plena? Ali bo mlad lev vpil iz svojega brloga, če ni ničesar dobil?',
        5: 'Ali lahko ptica pade v zanko na tla, kjer zanjo ni nobene pasti? Mar nekdo pobere zanko s tal in ni sploh ničesar ujel?',
        6: 'Mar bo šofar zatrobil v mestu in ljudstvo ne bo prestrašeno? Mar bo zlo v mestu in Gospod tega ni storil?',
        7: 'Zagotovo Gospod Bog ne bo storil ničesar, da ne bi svojo skrivnost razodeval svojim služabnikom prerokom.',
        8: 'Lev je zarjovel, kdo se ne bo bal? Gospod Bog je spregovoril, kdo ne bi prerokoval?',
        9: 'Razglasi v palačah pri Ašdódu in v palačah egiptovske dežele in reci: ›Zberite se na gorah Samarije in glejte velike nemire v njeni sredi in zatirane v njeni sredi.‹',
        10: 'Kajti ne znajo delati pravilno,« govori Gospod, »tisti, ki kopičijo nasilje in rop v svojih palačah.«',
        11: 'Zato tako govori Gospod Bog: »Nasprotnik bo celo naokoli dežele in tvojo moč bo privedel dol od tebe in tvoje palače bodo oplenjene.«',
        12: 'Tako govori Gospod: »Kakor pastir iz levjih ust izvleče dve nogi ali košček ušesa, tako bodo izvlečeni Izraelovi otroci, ki prebivajo v Samariji, v kotu postelje in na ležišču v Damasku.',
        13: 'Prisluhnite in pričujte v Jakobovi hiši,« govori Gospod Bog, Bog nad bojevniki,',
        14: '»da na dan, ko bom na njem obiskal Izraelove prestopke, bom obiskal tudi oltarje Betela in oltarni rogovi bodo odsekani in padli na tla.',
        15: 'Zimsko hišo bom udaril s poletno hišo [vred] in slonokoščene hiše bodo izginile in velike hiše bodo uničene,« govori Gospod.',
    },
    4: {
        1: '»Poslušajte to besedo, ve bašánske krave, ki ste na samarijski gori, ki stiskate uboge, ki drobite pomoči potrebne, ki svojim gospodarjem pravite: ›Prinesite in naj pijemo.‹',
        2: 'Gospod Bog je prisegel pri svoji svetosti, da, glejte, nad vas bodo prišli dnevi, ko vas bo odvedel proč s kavlji in vaše potomstvo s trnki.',
        3: 'Šle boste ven pri vrzelih, vsaka krava pri tisti, ki je pred njo, in vrgle jih boste v palačo,« govori Gospod.',
        4: '§ »Prihajate v Betel in grešite, pri Gilgálu množite prestopek in vsako jutro prinašajte svoje klavne daritve in svoje desetine po treh letih',
        5: 'in darujte žrtev zahvaljevanja s kvasom in razglašajte in objavljajte prostovoljne daritve, kajti to vam je všeč, oh vi, Izraelovi otroci,« govori Gospod Bog.',
        6: '»In tudi jaz sem vam dal čistost zob po vseh vaših mestih in pomanjkanje kruha po vseh vaših krajih. Vendar se niste vrnili k meni,« govori Gospod.',
        7: '»In tudi jaz sem zadržal dež pred vami, ko je bilo še tri mesece do žetve in mu dal, da dežuje nad enim mestom in dal, da ne dežuje nad drugim mestom. Na en kos je deževalo, kos pa, na katerega ni deževalo, se je posušil.',
        8: 'Tako so dva ali tri mesta tavala k enemu mestu, da pijejo vodo, toda niso bila nasičena. Vendar se niste vrnili k meni,« govori Gospod.',
        9: '»Udaril sem vas s kvarjenjem in plesnijo. Ko so se množili vaši vrtovi in vaši vinogradi in vaša figova drevesa in vaše oljke, jih je požrla kosmata gosenica. Vendar se niste vrnili k meni,« govori Gospod.',
        10: '»Med vas sem poslal kužno bolezen po načinu iz Egipta. Vaše mladeniče sem umoril z mečem in vaše konje odvedel proč in storil sem, da se smrad vaših taborov vzdigne do vaših nosnic, vendar se niste vrnili k meni,« govori Gospod.',
        11: '»Uničil sem nekatere izmed vas, kakor je Bog razdejal Sódomo in Gomóro in ste bili kakor kos tlečega lesa, izvlečenega iz gorenja, vendar se niste vrnili k meni,« govori Gospod.',
        12: '»Zato ti bom tako storil, oh Izrael in ker ti bom to storil, se pripravi, da srečaš svojega Boga, oh Izrael.',
        13: 'Kajti glej, tisti ki oblikuje gore in ustvarja veter in razglaša človeku, kaj je njegova misel, ki dela jutranjo temo in mendra na visokih krajih zemlje. Gospod, Bog nad bojevniki, je njegovo ime.«',
    },
    5: {
        1: 'Poslušajte to besedo, ki jo vzdigujem zoper vas, celó žalostinko, oh Izraelova hiša.',
        2: 'Devica Izrael je padla, ne bo več vstala, zapuščena je na svoji zemlji, tam ni nikogar, ki bi jo vzdignil.',
        3: 'Kajti tako govori Gospod Bog: »Mestu, ki je šlo ven po tisoč, jih preostane sto in tistemu, ki je šlo naprej po sto, jih preostane deset, Izraelovi hiši.«',
        4: 'Kajti tako govori Gospod Izraelovi hiši: »Iščite me in boste živeli,',
        5: 'toda ne iščite Betela niti ne vstopajte v Gilgál in ne prečkajte v Beeršébo, kajti Gilgál bo zagotovo šel v ujetništvo in Betel bo prišel v nič.',
        6: 'Iščite Gospoda in boste živeli, da ne izbruhne kakor ogenj v Jožefovi hiši in jo použije in tam ne bo nikogar, da bi jo gasil v Betelu.',
        7: 'Vi, ki prevračate sodbo v grenkobo in opuščate pravičnost na zemlji,',
        8: 'iščite njega, ki določa sedem zvezd in Orion in obrača senco smrti v jutro in dan mrači z nočjo, ki kliče po vodah morja in jih izliva na obličje zemlje, Gospod je njegovo ime,',
        9: 'ki jača oplenjenega zoper močnega, tako da bo oplenjeni prišel zoper trdnjavo.',
        10: 'Sovražijo tistega, ki graja v velikih vratih in prezirajo tistega, ki govori iskreno.',
        11: 'Ker kakor je torej vaše mendranje nad revnim in vi od njega jemljete bremena žita; zgradili ste hiše iz klesanega kamna, toda ne boste prebivali v njih; sadili ste prijetne vinograde, toda ne boste pili vina od njih.',
        12: 'Kajti jaz poznam vaše mnogotere prestopke in vaše mogočne grehe; stiskajo pravičnega, jemljejo podkupnino in v velikih vratih revne odvračajo od njihove pravice.',
        13: 'Zato bo v tem času razsoden molčal, kajti to je hud čas.',
        14: 'Iščite dobro in ne zla, da boste lahko živeli in tako bo Gospod, Bog nad bojevniki, z vami, kakor ste govorili.',
        15: 'Sovražite zlo in ljubite dobro in vzpostavite sodbo v velikih vratih. Morda bo Gospod, Bog nad bojevniki, milostljiv Jožefovemu preostanku.«',
        16: 'Zato Gospod, Bog nad bojevniki, Gospod, tako govori: »Tarnanje bo na vseh ulicah in na vseh glavnih cestah bodo govorili: ›Ojoj! Ojoj!‹ in poklicali bodo poljedelca, da žaluje in tiste, ki so vešči objokovanja, da tarnajo.',
        17: 'In v vseh vinogradih bo tarnanje, kajti jaz pojdem skozte,« govori Gospod.',
        18: '»Gorje vam, ki si želite Gospodovega dneva! Čemu vam bo to? Dan Gospodov je tema in ne svetloba.',
        19: 'Kakor če je človek pobegnil pred levom in ga je srečal medved; ali odšel v hišo in svojo roko naslonil na zid in ga je pičila kača.',
        20: 'Mar ne bo Gospodov dan tema in ne svetloba? Celo zelo temen in nobenega svetlikanja v njem?',
        21: 'Sovražim, preziram vaše praznične dni in nočem povonjati vaših slovesnih zborov.',
        22: 'Čeprav mi darujete žgalne daritve in jedilne daritve, jih ne bom sprejel niti se ne bom oziral na mirovne daritve vaših debelih živali.',
        23: 'Šum svojih pesmi vzemi proč od mene, kajti ne bom poslušal melodije tvojih lir.',
        24: 'Temveč naj sodba teče dol kakor vode in pravičnost kakor mogočen vodotok.',
        25: 'Mar ste mi darovali klavne daritve in jedilne daritve štirideset let v divjini, oh hiša Izraelova?',
        26: '§ Toda nosili ste šotor svojega Moloha in Kijúna, svojih podob, zvezdo svojega boga, kar ste si naredili zase.',
        27: 'Zatorej vam bom povzročil, da greste v ujetništvo onkraj Damaska,« govori Gospod, čigar ime je Bog nad bojevniki.',
    },
    6: {
        1: '»Gorje tistim, ki so v udobju na Sionu in zaupajo v samarijsko goro, ki se imenujejo vodje narodov, h katerim je prihajala Izraelova hiša!',
        2: 'Prečkajte v Kalne in poglejte in od tam pojdite v veliki Hamát. Potem pojdite dol v Gat Filistejcev. Mar so boljši kakor ta kraljestva? Je njihova meja večja kakor vaša meja?',
        3: 'Vi, ki zli dan polagate daleč stran in sedežu nasilja naredite, da pride blizu,',
        4: 'ki ležite na posteljah iz slonovine in se iztegujete na svojih ležiščih in jeste jagnjeta iz tropa in teleta iz srede hleva,',
        5: 'ki monotono pojete na zvok lire in si izmišljate glasbene instrumente, podobno kakor David;',
        6: 'ki pijete vino v skledicah in se mazilite z vodilnimi mazili. Toda niso užaloščeni zaradi Jožefove stiske.',
        7: 'Zato bodo sedaj šli ujeti s prvimi, ki gredo ujeti in gostija tistih, ki so se iztegovali, bo odstranjena.',
        8: 'Gospod Bog je prisegel pri samem sebi,« govori Gospod, Bog nad bojevniki, »preziram odličnost Jakoba in sovražim njegove palače, zato bom izročil mesto, z vsem, kar je v njem.',
        9: 'In zgodilo se bo, če tam ostane deset ljudi v eni hiši, da bodo umrli.',
        10: 'In njegov stric ga bo vzdignil in tisti, ki ga sežiga, da odnese kosti iz hiše in rekel bo tistemu, ki je pri straneh hiše: › Je tam še kdo s teboj?‹ Ta pa bo rekel: ›Ne.‹ Potem bo rekel: ›Molči, kajti ne smemo omenjati Gospodovega imena.‹',
        11: 'Kajti glej, Gospod zapoveduje in veliko hišo bo udaril z vrzelmi in majhno hišo z razpokami.',
        12: 'Mar bodo konji tekli po skali? Ali bo tam kdo oral z voli? Kajti sodbo ste obrnili v žolč in sad pravičnosti v pikasti mišjak.',
        13: 'Vi, ki se veselite v ničevi stvari, ki pravite: ›Mar nismo s svojo lastno močjo k sebi vzeli rogov?‹',
        14: 'Toda glejte, zoper vas bom dvignil narod, oh Izraelova hiša,« govori Gospod, Bog nad bojevniki, »in stiskali vas bodo od vstopanja v Hamát, do reke iz divjine.«',
    },
    7: {
        1: 'Tako mi je Gospod Bog pokazal in glej, oblikoval je kobilice v začetku poganjanja otave in glej, to je bila otava po kraljevih košnjah.',
        2: 'Pripetilo se je, ko so končale z objedanjem trave dežele, da sem nato rekel: »Oh Gospod Bog, odpusti, rotim te. Po kom bo Jakob vstal? Kajti majhen je.«',
        3: 'Gospod se je zaradi tega pokesal. »To ne bo,« govori Gospod.',
        4: 'Tako mi je Gospod Bog pokazal in glej, Gospod Bog je klical k pričkanju z ognjem in ta je požrl veliko globino in pojedel del.',
        5: 'Potem sem rekel: »Oh Gospod Bog, odnehaj, rotim te. Po kom bo Jakob vstal? Kajti majhen je.«',
        6: 'Gospod se je zaradi tega pokesal: »Tudi to se ne bo zgodilo,« govori Gospod Bog.',
        7: 'Zato mi je pokazal in glej, Gospod je stal na zidu, narejenem s svinčnico, s svinčnico v svoji roki.',
        8: 'Gospod mi je rekel: »Amos, kaj vidiš?« Rekel sem: »Svinčnico.« Potem je Gospod rekel: »Glej, postavil bom svinčnico v sredo svojega ljudstva Izraela. Ne bom več ponovno šel mimo njega',
        9: 'in Izakovi visoki kraji bodo zapuščeni in Izraelova svetišča bodo opustošena in z mečem se bom dvignil zoper Jerobeámovo hišo.«',
        10: 'Potem je Amacjá, duhovnik iz Betela, poslal k Jerobeámu, Izraelovemu kralju, rekoč: »Amos se je zarotil zoper tebe v sredi Izraelove hiše. Dežela ni zmožna prenesti vseh njegovih besed.',
        11: 'Kajti tako govori Amos: ›Jerobeám bo umrl pod mečem in Izrael bo zagotovo iz svoje lastne dežele odveden v ujetništvo.‹«',
        12: 'Amacjá je prav tako rekel Amosu: »Oh ti videc, pojdi, pobegni proč v Judovo deželo in tam jej kruh in tam prerokuj,',
        13: 'toda ne prerokuj ponovno pri Betelu, kajti to je kraljeva kapela in to je kraljevi dvor.«',
        14: 'Potem je Amos odgovoril in rekel Amacjáju: »Jaz nisem bil nikakršen prerok niti nisem bil prerokov sin, temveč sem bil črednik in obiralec sadu egiptovske smokve',
        15: 'in Gospod me je vzel, medtem ko sem sledil tropu in Gospod mi je rekel: ›Pojdi, prerokuj mojemu ljudstvu Izraelu.',
        16: 'Zdaj torej poslušaj Gospodovo besedo: ›Praviš: ›Ne prerokuj zoper Izrael in ne kapljaj svoje besede zoper Izakovo hišo.‹',
        17: 'Zato tako govori Gospod: ›Tvoja žena bo pocestnica v mestu in tvoji sinovi in tvoje hčere bodo padli pod mečem in tvoja dežela bo razdeljena z vrvico, ti pa boš umrl v oskrunjeni deželi, in Izrael bo zagotovo odšel v ujetništvo, iz svoje dežele.‹«',
    },
    8: {
        1: 'Tako mi je pokazal Gospod Bog in glej, košara poletnega sadja.',
        2: 'Rekel je: »Amos, kaj vidiš?« Rekel sem: »Košaro poletnega sadja.« Potem mi je Gospod rekel: »Konec je prišel nad moje ljudstvo Izrael; ne bom ponovno šel mimo njih.',
        3: 'Tempeljske pesmi bodo vpitje na ta dan,« govori Gospod Bog. »Na vsakem kraju bo mnogo trupel; metali jih bodo v tišini.',
        4: 'Poslušajte to, oh vi, ki pogoltnete pomoči potrebnega, celo da revnemu v deželi storite, da propade,',
        5: 'rekoč: ›Kdaj bo minil mlaj, da bomo lahko prodajali žito? In šabat, da bomo lahko odpremili pšenico, naredili škaf majhen in šekel velik in s prevaro izkrivili tehtnice?',
        6: 'Da lahko ubogega kupimo za srebro in pomoči potrebnega za par čevljev, da, in prodamo pleve od pšenice?‹«',
        7: 'Gospod je prisegel pri Jakobovi odličnosti: »Zagotovo ne bom nikoli pozabil nobenega izmed njihovih del.',
        8: 'Mar ne bo zemlja zaradi tega trepetala in vsak človek žaloval, ki prebiva na njej? Vstala bo v celoti kakor poplava, vržena bo ven in potopljena, kakor z egiptovsko poplavo.',
        9: 'Na tisti dan se bo zgodilo,« govori Gospod Bog, »da bom soncu povzročil, da zaide opoldan in na jasen dan bom zatemnil zemljo.',
        10: 'Vaše praznike bom obrnil v žalovanje in vse vaše pesmi v žalostinko in privedel bom vrečevino na vsa ledja in plešavost na vsako glavo in naredil jo bom kakor žalovanje za edinim sinom in njen konec kakor grenek dan.',
        11: 'Glejte, pridejo dnevi,« govori Gospod Bog, »da bom v deželo poslal lakoto, ne lakote po kruhu niti žeje po vodi, temveč [lakoto] po poslušanju Gospodovih besed.',
        12: 'Tavali bodo od morja do morja in od severa, celo do vzhoda, tekali bodo sem ter tja, da iščejo besedo od Gospoda, pa je ne bodo našli.',
        13: 'Na tisti dan bodo lepe device in mladeniči slabeli zaradi žeje.',
        14: 'Tisti, ki prisegajo pri grehu Samarije in pravijo: ›Tvoj bog, oh Dan, živi;‹ in: ›Način Beeršébe živi;‹ celo padli bodo in nikoli več ne bodo ponovno vstali.«',
    },
    9: {
        1: 'Videl sem Gospoda stati na oltarju in rekel je: »Udari vratno preklado, da se bodo podboji lahko tresli, in ureži jih na glavi, vse izmed njih in jaz bom zadnje izmed njih ubil z mečem in kdor izmed njih beži, ne bo pobegnil proč in kdor se izmed njih umika, ne bo osvobojen.',
        2: 'Čeprav kopljejo v pekel, jih bo moja roka vzela od tam. Čeprav plezajo gor do nebes, jih bom od tam privedel dol.',
        3: 'Čeprav se skrijejo na vrhu Karmela, jih poiščem in vzamem od tam. Čeprav so skriti pred mojim pogledom na dnu morja, bom tam zapovedal kači in ta jih bo pičila.',
        4: 'Čeprav gredo v ujetništvo pred svojimi sovražniki, bom tja poslal meč in ta jih bo ubil in svoje oči bom naravnal nanje za zlo in ne za dobro.«',
        5: 'Gospod Bog nad bojevniki je tisti, ki se dotika dežele in ta se bo stopila in vsi, ki prebivajo v njej, bodo žalovali. In ta se bo vzdignila v celoti kakor poplava in potopljena bo kakor z egiptovsko poplavo.',
        6: 'On je tisti, ki gradi svoja nadstropja v nebesih in je utemeljil svoje krdelo na zemlji. On, ki kliče za morskimi vodami in jih izliva na obličje zemlje. Gospod je njegovo ime.',
        7: '» Ali mi niste kakor otroci Etiopijcev, oh Izraelovi otroci?« govori Gospod: »Mar nisem jaz Izraela privedel gor iz egiptovske dežele? In Filistejce iz Kaftorja in Sirce iz Kira?',
        8: 'Glejte, oči Gospoda Boga so nad grešnim kraljestvom in uničil ga bom izpred obličja zemlje; le, da ne bom popolnoma uničil Jakobove hiše,« govori Gospod.',
        9: '»Kajti glejte, zapovedal bom in Izraelovo hišo bom presejal med vse narode, kakor je žito presejano na situ, vendar niti najmanjše zrno ne bo padlo na zemljo.',
        10: 'Vsi grešniki mojega ljudstva bodo umrli pod mečem, ki pravijo: ›Zlo nas ne bo dohitelo niti nas ne bo srečalo.‹',
        11: 'Na tisti dan bom vzdignil Davidovo šotorsko svetišče, ki je padlo in zaprl njegove vrzeli. In vzdignil bom njegove ruševine in zgradil ga bom kakor v dneh davnine,',
        12: 'da bodo lahko vzeli v last preostanek Edóma in vseh poganov, ki so imenovani z mojim imenom,« govori Gospod, ki to dela.',
        13: '»Glejte, pridejo dnevi,« govori Gospod, »ko bo orač prehitel žanjca in tlačitelj grozdja tistega, ki seje seme, in gore bodo kapljale sladko vino in vsi hribi se bodo topili.',
        14: 'Ponovno bom privedel ujetništvo svojega ljudstva Izraela in zgradili bodo opustošena mesta in jih poselili, in sadili bodo vinograde in pili njihovo vino; prav tako bodo naredili vrtove in jedli njihov sad.',
        15: 'Jaz jih bom zasadil na njihovi deželi in ne bodo več potegnjeni iz svoje dežele, ki sem jim jo dal,« govori Gospod, tvoj Bog.',
    },
}
